package pe.edu.upeu.pago.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.data.domain.PageRequest;import pe.edu.upeu.pago.repository.*;
@Component @RequiredArgsConstructor public class FinanzasProgramadas {
 private final ConciliacionPagoService conciliacion;private final LiquidacionService liquidaciones;private final OrdenCompraRepository ordenes;private final OrdenCertificadoRepository certificados;
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(FinanzasProgramadas.class);
 @Scheduled(fixedDelayString="${kido.pagos.conciliacion-ms:300000}",initialDelayString="30000") public void conciliar(){for(Long id:ordenes.porConciliar(pe.edu.upeu.pago.entity.OrdenCompra.EstadoOrden.APROBADA,PageRequest.of(0,100)))try{conciliacion.compra(id);}catch(Exception e){log.warn("Orden {} pendiente de conciliación; se reintentará [{}]",id,e.getClass().getSimpleName());}for(Long id:certificados.porConciliar(pe.edu.upeu.pago.entity.OrdenCertificado.EstadoOrden.APROBADA,PageRequest.of(0,100)))try{conciliacion.certificado(id);}catch(Exception e){log.warn("Certificado {} pendiente de conciliación [{}]",id,e.getClass().getSimpleName());}for(var o:ordenes.findByRequiereRevocacionTrue(PageRequest.of(0,100)))try{conciliacion.revocarAcceso(o.getId());}catch(Exception e){log.warn("Revocación de acceso de orden {} pendiente [{}]",o.getId(),e.getClass().getSimpleName());}}
 @Scheduled(cron="0 10 0 1,16 * *",zone="America/Lima") public void prepararQuincena(){try{var r=liquidaciones.generar(null);log.info("Preparadas {} liquidaciones quincenales; no se realizaron transferencias",r.creadas());}catch(Exception e){log.error("La liquidación quincenal requiere revisión [{}]",e.getClass().getSimpleName());}}
}
